package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/planning/okr") public class OkrController {private final OkrService s; public OkrController(OkrService s){this.s=s;} @PostMapping("/cycles") public Mono<OkrCycleView> cycle(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateOkrCycleRequest r){return s.createCycle(o,r);} @GetMapping("/cycles")public Flux<OkrCycleView> cycles(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return s.cycles(o);} @PostMapping("/objectives")public Mono<OkrObjectiveView> objective(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateOkrObjectiveRequest r){return s.createObjective(o,r);} @GetMapping("/cycles/{cycleId}/objectives")public Flux<OkrObjectiveView> objectives(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID cycleId){return s.objectives(o,cycleId);} @PostMapping("/objectives/{objectiveId}/key-results")public Mono<OkrKeyResultView> keyResult(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID objectiveId,@Valid@RequestBody CreateOkrKeyResultRequest r){return s.createKeyResult(o,objectiveId,r);} @GetMapping("/objectives/{objectiveId}/key-results")public Flux<OkrKeyResultView> keyResults(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID objectiveId){return s.keyResults(o,objectiveId);} @PostMapping("/key-results/{keyResultId}/check-ins")public Mono<OkrCheckInView> checkIn(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID keyResultId,@Valid@RequestBody CreateOkrCheckInRequest r){return s.checkIn(o,keyResultId,r);} @GetMapping("/key-results/{keyResultId}/check-ins")public Flux<OkrCheckInView> checkIns(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID keyResultId){return s.checkIns(o,keyResultId);}}
